------------------------------------------------------ public
---@param dialog UIActivityTotalTopupPanel
function UIActivityPromoterCell:Refresh(taskDojo, index, dialog)

    if isTable(taskDojo) == false then
        printError("查出异常 task dojo " .. tostring(index) )
        return
    end

    self.dialog = dialog
    self.taskDojo = taskDojo
    self.taskVO = UIActivityPromoterUtils.GetActivityPromoterTasksVO( checkNumber(self.taskDojo.taskId) )
    self.index = index

    local status = self.taskDojo.status
    --status = 1 -- !!! debug

    if status == 0 then   -- CanNotReceive
        CfUtils.SetActive( self.TxtTaskIng, true )
        CfUtils.SetActive( self.FontStyleButton, false )
        CfUtils.SetActive( self.Black, false )
        CfUtils.SetActive( self.ImgFinish, false )

    elseif status == 1 then  -- CanReceive
        CfUtils.SetActive( self.TxtTaskIng, false )
        CfUtils.SetActive( self.FontStyleButton, true )
        CfUtils.SetActive( self.Black, false )
        CfUtils.SetActive( self.ImgFinish, false )

    elseif status == 2 then  -- Received
        CfUtils.SetActive( self.TxtTaskIng, false )
        CfUtils.SetActive( self.FontStyleButton, false )
        CfUtils.SetActive( self.Black, true )
        CfUtils.SetActive( self.ImgFinish, true )
    else
        printError("变量 btnState 异常 = " .. tostring(self.btnState) )
        CfUtils.SetActive( self.TxtTaskIng, false )
        CfUtils.SetActive( self.FontStyleButton, false )
        CfUtils.SetActive( self.Black, false )
        CfUtils.SetActive( self.ImgFinish, false )
    end

    -- 绘制 左侧文本进度条内容
    local ProgressBar = self.TextDescribe.transform:Find("ProgressGroup/ProgressBar")
    local slider = KTool.GetComponent(ProgressBar.gameObject, typeof(Slider))
    local TextNum = self.TextDescribe.transform:Find("ProgressGroup/TextNum")

    local progress = checkNumber(self.taskDojo.progress)
    local totalNum = checkNumber(self.taskVO.taskContenNum)
    CfUtils.FillText( TextNum.gameObject, string.format("<size=34><color=#464646>%s</color></size>/%s", progress, totalNum) )
    slider.value = progress / totalNum
    CfUtils.FillText( self.TextDescribe, tostring(self.taskDojo.desc) )


    -- 绘制 奖励道具图标
    ---@type GoodNodeMB
    local scr = CfUtils.GetLuaScr(self.GoodNode, "Game.Behaviours.GoodNodeMB")
    scr:Reload({
        goodsId = self.taskVO.rewardId,
        text = string.format("x %d", self.taskVO.rewardNum),
        isShowNo = true
    })
    scr:SetClickButtonAction(function()
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.taskVO.rewardId)
        GameUtils.ShowCommonTipsBoard( self.GoodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id )
    end)

end


function UIActivityPromoterCell:_OnClick_FontStyleButton()
    if isNull(self.dialog) or isNull(self.index) then 
        printError("数据未准备好, 请检查调用时序")
        return
    end 

    GameUtils.Request( "Activity/spreadDrawTask", {activityUuid = self.dialog.activityUuid, id = checkNumber(self.index) }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            --printError("data = " .. table.dump(response.data) )

            Events.Broadcast(Constants.EventNames.PromoterRefresh)

            -- 领取宝箱数据, 
            GoodsUtils.DrawRewards( response.data.rewards )

            -- 播放窗口动画:
            UIModule.OpenDialog({ 
                id = Constants.UITypeIds.UICommonRewardPop, 
                parameters = { rewards = response.data.rewards } 
            })
        end
    end)
end



function UIActivityPromoterCell:PlayFadeInAnim(index0Based)
    if not isNull(self.AnimRoot) then
        CfUtils.PlayAnimator(self.AnimRoot, "Wait")
        CfUtils.PlayDelayShowAnimate(self.AnimRoot, 1, ((index0Based or 1) - 1)  * 0.06)
        --print("PlayFadeInAnim")
    end
end


function UIActivityPromoterCell:PlayInitAnim()
    if not isNull(self.AnimRoot) then
        --print("PlayInitAnim")
        CfUtils.PlayAnimator(self.AnimRoot, "Default")
    end
end


return UIActivityPromoterCell
 
 